    result_size = result_size.wrapping_add(clcounts[16].wrapping_mul(2));
    result_size = result_size.wrapping_add(clcounts[17].wrapping_mul(3));
    result_size = result_size.wrapping_add(clcounts[18].wrapping_mul(7));

    free(rle as *mut c_void);
    free(rle_bits as *mut c_void);
    result_size
}
